import React from 'react';

function ProductCard({ product }) {
  return <li><strong>{product.name}</strong><span>المخزون: {product.stock}</span></li>;
}

export default function App() {
  const products = [{id: 1, name: 'قلم', stock: 0}, {id: 2, name: 'دفتر', stock: 3}];
  return <ul>{products.map(product => <ProductCard key={product.id} product={product} />)}</ul>;
}

