function stockValue(text) {
  if (!text.trim()) return null;
  const value = Number(text);
  return Number.isInteger(value) && value >= 0 ? value : null;
}
console.log(stockValue(''));
console.log(stockValue('0'));
console.log(stockValue('-1'));
console.log(stockValue('1.5'));

import React, { useEffect, useState } from 'react';

async function sampleProducts(query, signal) {
  await Promise.resolve();
  signal.throwIfAborted();
  const products = [{id: 1, name: 'قلم'}];
  return products.filter(product => product.name.includes(query));
}

export default function App({ query = '', loadProducts = sampleProducts }) {
  const [message, setMessage] = useState('جارٍ التحميل');
  useEffect(() => {
    let active = true;
    const controller = new AbortController();
    async function load() {
      setMessage('جارٍ التحميل');
      try {
        const data = await loadProducts(query, controller.signal);
        if (!Array.isArray(data)) throw new Error('قائمة غير صالحة');
        if (active) setMessage(data.length ? 'وصلت المنتجات' : 'القائمة فارغة');
      } catch (error) {
        if (active) setMessage(error.message);
      }
    }
    load();
    return () => { active = false; controller.abort(); };
  }, [query, loadProducts]);
  return <p role="status">{message}</p>;
}

import React from 'react';

export default function ProductList({ products = [] }) {
  if (products.length === 0) return <p role="status">القائمة فارغة</p>;
  return <ul>{products.map(product => <li key={product.id}>{product.name}</li>)}</ul>;
}

import React from 'react';

function Summary({ count }) {
  return <p>عدد النتائج: {count}</p>;
}

export default function App() {
  const products = [{id: 1, name: 'قلم', stock: 0}, {id: 2, name: 'دفتر', stock: 3}];
  const inStock = products.filter(product => product.stock > 0);
  return <main><h1>كتالوجي</h1><Summary count={inStock.length} />
    <ul>{inStock.map(product => <li key={product.id}>{product.name}</li>)}</ul></main>;
}
